<script>
import gql from 'graphql-tag'
import { onLogin } from '../../vue-apollo';
import { mapMutations } from 'vuex'


export default {
    name: 'Login',
    metaInfo: {
		title: 'Ingresar',
	},
    
    data() {
        return {
            email: '',
            pass: '',
            loginError:false,
            loginIn:false,
        }
    },
    beforeMount(){
        this.logout();
    },
    methods: {
		...mapMutations(['authSuccess','logout']),
        login() {
            this.loginError=false;
            if(!this.loginIn){
                this.loginIn = true;

                return this.$apollo.mutate({
                    mutation: gql`mutation userLogin($email:String!, $password:String! , $accessTo: String!){
                        medicLogin( email: $email, password: $password, accessTo: $accessTo ){
                            token
							medic{
								id
								name
								lastname
								email
							}
                        }
                    }`,
                    variables: {
                        email: this.email,
						password: this.pass,
						accessTo: 'admin'
                    },
                })
                .then( data => {
					console.log('login', data)
					let access_token = data.data.medicLogin.token
                    let logged_medic = data.data.medicLogin.medic
                    onLogin(this.$apollo.provider.defaultClient, access_token, logged_medic).then(() => { 
						console.log('asds')
                        this.authSuccess({token:access_token, loggedMedic: logged_medic})
						this.loading = false
						this.$emit('loadMe')
                        this.$router.push('/prescriptions/create')
                    });
                })
                .catch((errors) => {
                    console.log(errors)
                    this.loginError=true;
                    this.loginIn = false;
				});



                // axios.post('/auth/medic/login', { email: this.email, password: this.pass })
                // .then(request => {
                //     if(request.data.access_token){
                //         let access_token = request.data.access_token;
                //         let logged_medic = request.data.user;
                //         onLogin(this.$apollo.provider.defaultClient, access_token, logged_medic).then(() => { 
                //             this.authSuccess({token:access_token, loggedMedic: logged_medic});
                //             this.$ga.event('medics', 'medic-logged', logged_medic.email)
                //             this.$router.push('/');
                //         });				
                //     }else{
                //         this.loginError=true;
                //         this.loginIn = false;
                //     }
                // })
                // .catch(() => 
                // {
                //     this.loginError=true;
                //     this.loginIn = false;
                // })
            }
			
		},
    }
}
